/**
 * TRUECOLOURS — production-oriented paint catalogue seed
 * -----------------------------------------------------
 * This file intentionally stores a curated, market-aware seed dataset rather than
 * fake placeholder entries. It is designed to support the production flow:
 * Brand → Model → Year → Market → OEM colours. It remains easy to grow and can be
 * replaced by Supabase/PostgreSQL later without changing the front-end contract.
 */

export interface PaintColor {
  code: string;
  name: string;
  hex: string;
  yearFrom: number;
  yearTo: number;
  verified: boolean;
  finish?: string;
  market?: string;
  manufacturer?: string;
  notes?: string;
  brand?: string;
  model?: string;
}

export interface VehicleModel {
  model: string;
  colors: PaintColor[];
}

export interface VehicleBrand {
  brand: string;
  models: VehicleModel[];
}

