export function getBrandNames(): string[] {
  return PAINT_DATABASE.map((entry) => entry.brand).sort((a, b) => a.localeCompare(b));
}

export function getModelsForBrand(brand: string): string[] {
  const found = PAINT_DATABASE.find((entry) => entry.brand === brand);
  return found ? found.models.map((model) => model.model) : [];
}

export function getMarketsForVehicle(brand: string, model: string): string[] {
  const foundBrand = PAINT_DATABASE.find((entry) => entry.brand === brand);
  if (!foundBrand) return [];

  const markets = new Set<string>();
  const foundModel = foundBrand.models.find((entry) => entry.model === model);
  if (!foundModel) return [];

  for (const paint of foundModel.colors) {
    if (paint.market) markets.add(paint.market);
  }

  return Array.from(markets).sort((a, b) => a.localeCompare(b));
}

export function findColorsForVehicle(
  brand: string,
  model: string,
  year: number,
  market?: string
): PaintColor[] {
  const foundBrand = PAINT_DATABASE.find((entry) => entry.brand === brand);
  const foundModel = foundBrand?.models.find((entry) => entry.model === model);
  if (!foundModel) return [];

  return foundModel.colors.filter((color) => {
    const inYear = year >= color.yearFrom && year <= color.yearTo;
    const inMarket = !market || !color.market || color.market === market;
    return inYear && inMarket;
  });
}

export interface CodeSearchResult extends PaintColor {
  brand: string;
  model: string;
}

export function searchByCode(query: string): CodeSearchResult[] {
  const q = query.trim().toLowerCase();
  if (!q) return [];

  const results: CodeSearchResult[] = [];
  for (const brand of PAINT_DATABASE) {
    for (const model of brand.models) {
      for (const color of model.colors) {
        const codeMatch = color.code.toLowerCase().includes(q);
        const nameMatch = color.name.toLowerCase().includes(q);
        if (codeMatch || nameMatch) {
          results.push({ ...color, brand: brand.brand, model: model.model });
        }
      }
    }
  }

  return results;
}
